removed.rule:
.alerts-filters select,
.alerts-filters .search-input {
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--ion-border);
    border-radius: var(--radius);
    font-size: 0.875rem;
    background: var(--bg-secondary);
}

.side-panel .list-group {
    display: flex;
    flex-direction: column;
    gap: 8px;
    max-height: 240px;
    overflow-y: auto;
}

.cases-modal-body .form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    background: var(--bg-primary);
    border: 1px solid var(--ion-border);
    border-radius: var(--radius);
    color: var(--text-primary);
    font-size: 0.85rem;
    box-sizing: border-box;
}

.nav-links > li > a:not(.nav-dropdown-toggle) {
    color: var(--text-secondary);
    text-decoration: none;
    padding: 0.5rem 0.85rem;
    border-radius: var(--radius);
    font-size: 0.82rem;
    font-weight: 600;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    transition: all 0.2s ease;
    position: relative;
    white-space: nowrap;
    border: 1px solid transparent;
}

.nav-links > li > a:not(.nav-dropdown-toggle):hover {
    color: var(--primary);
    background: var(--primary-dim);
    border-color: var(--border-bright);
    text-shadow: var(--glow-sm);
}

body[data-page="workforce_orbat"] .wf-tree ul{
    display: flex; align-items: flex-start; justify-content: center;
    padding: 26px 0 0; margin: 0; position: relative;
}

body[data-page="workforce_orbat"] .wf-tree li{
    list-style: none; position: relative;
    display: flex; flex-direction: column; align-items: center;
    padding: 26px 10px 0;
}

body[data-page="workforce_orbat"] .wf-tree li::before, body[data-page="workforce_orbat"] .wf-tree li::after{
    content: ''; position: absolute; top: 0; right: 50%;
    border-top: 2px solid var(--wf-line); width: 50%; height: 26px;
}

body[data-page="workforce_orbat"] .wf-tree li:last-child::before{
    border-right: 2px solid var(--wf-line); border-radius: 0 8px 0 0;
}

body[data-page="workforce_orbat"] .wf-tree ul ul::before{
    content: ''; position: absolute; top: 0; left: 50%;
    border-left: 2px solid var(--wf-line); width: 0; height: 26px;
}

body[data-page="daily_standup_slides"] .deck-slide.title-slide .deck-title{
    background: linear-gradient(180deg, #f8fafc 0%, #94a3b8 100%);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent;
  }

body[data-page="observables"] .header-actions .badge{
    background: var(--warning);
    color: #000;
    padding: 0.15rem 0.4rem;
    border-radius: 10px;
    font-size: 0.7rem;
    margin-left: 0.3rem;
}

body[data-page="observables"] .observables-filters select, body[data-page="observables"] .observables-filters .search-input{
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--ion-border);
    border-radius: var(--radius);
    font-size: 0.875rem;
    background: var(--bg-secondary);
    color: var(--text-primary);
    transition: border-color 0.2s;
}

.pcap-progress .progress-bar-outer {
    height: 6px; border-radius: 3px; background: var(--bg-secondary); overflow: hidden;
}

.pcap-progress .progress-bar-inner {
    height: 100%; width: 0; background: var(--accent); border-radius: 3px;
    transition: width .3s; animation: pulse-bar 1.5s ease-in-out infinite;
}
